// Import docs/struct-layouts.csv's generated C into the program.
//
// Usage:
//   analyzeHeadless ... -process <program> -noanalysis
//     -postScript ImportStructs.java C:/Users/Happy/.cache/ow-struct-layouts.c
//
// The C source is generated by dev/gh_apply_types.py from
// docs/struct-layouts.csv; the docs are the source, this script only applies
// them to the clean program.
import ghidra.app.script.GhidraScript;
import ghidra.app.util.cparser.C.CParser;
import ghidra.program.model.data.DataType;
import ghidra.program.model.data.DataTypeConflictHandler;
import ghidra.program.model.data.DataTypeManager;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;

public class ImportStructs extends GhidraScript {
    @Override
    public void run() throws Exception {
        String[] args = getScriptArgs();
        if (args.length < 1) {
            println("usage: ImportStructs <layouts.c>");
            return;
        }
        Path path = Paths.get(args[0]);
        String source = Files.readString(path, StandardCharsets.UTF_8);
        DataTypeManager dtm = currentProgram.getDataTypeManager();
        // CParser.parse returns the parsed type but does not add it to the
        // program's manager. Split the file at each top-level struct and add
        // every one with the declared padding.
        int added = 0;
        for (String part : source.split("(?=\\nstruct )")) {
            if (!part.contains("struct ") || !part.contains(";")) {
                continue;
            }
            CParser parser = new CParser(dtm);
            parser.setParseFileName(path.getFileName().toString());
            DataType dt = parser.parse(part);
            if (dt == null) {
                println("IMPORT no type: " + parser.getParseMessages());
                continue;
            }
            DataType stored = dtm.addDataType(dt, DataTypeConflictHandler.REPLACE_HANDLER);
            println("IMPORT " + stored.getPathName() + " len=" + stored.getLength()
                + " messages=" + parser.getParseMessages());
            added++;
        }
        println("IMPORT added=" + added);
    }
}
